import {useMutation, useQueryClient} from '@tanstack/react-query';
import {apiClient} from '@common/http/query-client';
import {ChatMessage, SendMessagePayload} from '../chat-types';
import {toast} from '@ui/toast/toast';
import {useAuth} from '@common/auth/use-auth';

interface SendMessageResponse {
  message: ChatMessage;
}

export function useSendMessage(conversationId: number) {
  const queryClient = useQueryClient();
  const {user} = useAuth();

  return useMutation({
    mutationFn: async (payload: SendMessagePayload) => {
      const maxRetries = 2;
      let lastError: any;

      for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
          if (attempt > 0) {
            await new Promise(resolve => setTimeout(resolve, Math.min(1000 * Math.pow(2, attempt - 1), 3000)));
          }

          const response = await apiClient.post<SendMessageResponse>(
            `conversations/${conversationId}/messages`,
            payload,
          );

          return response.data.message;
        } catch (error: any) {
          lastError = error;
          const isNetworkError = !error?.response;
          const isTimeout = error?.code === 'ECONNABORTED' || error?.message?.includes('timeout');
          const isServerError = error?.response?.status >= 500;

          // Only retry on network errors, timeouts, or server errors
          if ((isNetworkError || isTimeout || isServerError) && attempt < maxRetries) {
            continue;
          }

          // Don't retry on client errors (4xx)
          throw error;
        }
      }

      // If all retries failed, throw the last error
      throw lastError;
    },

    onMutate: async newMessage => {
      const tempId = `temp-${Date.now()}`;
      const startTime = Date.now();

      // Cancel outgoing refetches
      await queryClient.cancelQueries({
        queryKey: ['chat', 'conversation', conversationId],
      });

      // Snapshot previous value
      const previous = queryClient.getQueryData([
        'chat',
        'conversation',
        conversationId,
      ]);

      // Optimistically update with temp message
      queryClient.setQueryData(
        ['chat', 'conversation', conversationId],
        (old: any) => {
          if (!old) return old;
          
          // Clean up any old failed temp messages first
          const cleanedMessages = (old.messages?.data || []).filter(
            (msg: any) => !(typeof msg.id === 'string' && msg.id.startsWith('temp-') && msg.failed)
          );
          
          return {
            ...old,
            messages: {
              ...old.messages,
              data: [
                {
                  id: tempId,
                  body: newMessage.body,
                  user_id: user?.id,
                  conversation_id: conversationId,
                  created_at: new Date().toISOString(),
                  sending: true,
                  failed: false,
                  user: user,
                  attachments: newMessage.attachments?.map((id: number) => ({ id })) || [],
                },
                ...cleanedMessages,
              ],
            },
          };
        },
      );
      
      return {previous, tempId, startTime};
    },

    onError: (err, vars, context) => {
      const duration = context?.startTime ? Date.now() - (context as any).startTime : null;
      const errorDetails = {
        error: err,
        errorType: err instanceof Error ? err.constructor.name : typeof err,
        errorMessage: err instanceof Error ? err.message : String(err),
        payload: vars,
        conversationId,
        tempId: (context as any)?.tempId,
        userId: user?.id,
        response: (err as any)?.response,
        status: (err as any)?.response?.status,
        statusText: (err as any)?.response?.statusText,
        data: (err as any)?.response?.data,
        duration,
        timestamp: new Date().toISOString(),
        networkError: !(err as any)?.response,
        timeout: (err as any)?.code === 'ECONNABORTED' || (err as any)?.message?.includes('timeout'),
      };
      
      // Log to a persistent store if available (for debugging)
      if (typeof window !== 'undefined' && window.localStorage) {
        try {
          const errorLogs = JSON.parse(localStorage.getItem('chat_error_logs') || '[]');
          const logEntry = {
            ...errorDetails,
            date: new Date().toISOString(),
            // Clean up circular references
            error: {
              message: errorDetails.errorMessage,
              type: errorDetails.errorType,
              name: (err as any)?.name,
              code: (err as any)?.code,
            },
            response: errorDetails.response ? {
              status: errorDetails.status,
              statusText: errorDetails.statusText,
              data: errorDetails.data,
            } : null,
          };
          errorLogs.push(logEntry);
          // Keep only last 50 errors
          const recentLogs = errorLogs.slice(-50);
          localStorage.setItem('chat_error_logs', JSON.stringify(recentLogs));
          
          // Also expose a global function to view logs
          (window as any).getChatErrorLogs = () => {
            return JSON.parse(localStorage.getItem('chat_error_logs') || '[]');
          };
          
          (window as any).clearChatErrorLogs = () => {
            localStorage.removeItem('chat_error_logs');
          };
        } catch (e) {
        }
      }
      
      // Mark the temp message as failed instead of rolling back
      queryClient.setQueryData(
        ['chat', 'conversation', conversationId],
        (old: any) => {
          if (!old) return old;
          
          const tempId = (context as any)?.tempId;
          const updatedMessages = (old.messages?.data || []).map((msg: any) => {
            // Match by tempId if available, otherwise match any sending temp message
            const isTargetMessage = tempId 
              ? msg.id === tempId
              : (typeof msg.id === 'string' && msg.id.startsWith('temp-') && msg.sending);
              
            if (isTargetMessage) {
              return {
                ...msg,
                sending: false,
                failed: true,
                error: (err as any)?.response?.data?.message || 
                       (err as any)?.message || 
                       'Failed to send message',
              };
            }
            return msg;
          });
          
          return {
            ...old,
            messages: {
              ...old.messages,
              data: updatedMessages,
            },
          };
        },
      );
      
      const errorMessage = (err as any)?.response?.data?.message || 
                          (err as any)?.response?.data?.errors?.body?.[0] ||
                          (err as any)?.message || 
                          'Failed to send message';
      toast.danger(errorMessage);
    },

    onSuccess: (data, vars, context) => {
      // Remove temp message before invalidating
      queryClient.setQueryData(
        ['chat', 'conversation', conversationId],
        (old: any) => {
          if (!old) return old;
          
          // Remove temp messages
          const cleanedMessages = (old.messages?.data || []).filter(
            (msg: any) => !(typeof msg.id === 'string' && msg.id.startsWith('temp-'))
          );
          
          return {
            ...old,
            messages: {
              ...old.messages,
              data: cleanedMessages,
            },
          };
        },
      );
      
      // Invalidate to refetch with real data
      queryClient.invalidateQueries({
        queryKey: ['chat', 'conversation', conversationId],
      });
      queryClient.invalidateQueries({
        queryKey: ['chat', 'conversations'],
      });
    },
  });
}
