import {useQuery} from '@tanstack/react-query';
import {apiClient} from '@common/http/query-client';
import {ChatConversation} from '../chat-types';

interface FetchConversationsResponse {
  conversations: {
    data: ChatConversation[];
  };
}

export function useFetchConversations() {
  return useQuery({
    queryKey: ['chat', 'conversations'],
    queryFn: () =>
      apiClient
        .get<FetchConversationsResponse>('conversations')
        .then(response => response.data.conversations.data),
  });
}
