import { getBootstrapData } from '@ui/bootstrap-data/bootstrap-data-store';
import { message } from '@ui/i18n/message';
import { MessageDescriptor } from '@ui/i18n/message-descriptor';
import { useDialogContext } from '@ui/overlays/dialog/dialog-context';
import { toast } from '@ui/toast/toast';
import { MouseEvent, useCallback } from 'react';

type ActionType = 'like' | 'follow' | 'play' | 'add-to-library';

function getActionMessage(actionType: ActionType): {
  notLoggedIn: MessageDescriptor;
  noPermission: MessageDescriptor;
} {
  switch (actionType) {
    case 'like':
      return {
        notLoggedIn: message('To like music, you need to register for a free account'),
        noPermission: message('Your current plan does not allow liking music. Please upgrade your package'),
      };
    case 'follow':
      return {
        notLoggedIn: message('To follow artists, you need to register for a free account'),
        noPermission: message('Your current plan does not allow following artists. Please upgrade your package'),
      };
    case 'add-to-library':
      return {
        notLoggedIn: message('To add to library, you need to register for a free account'),
        noPermission: message('Your current plan does not allow adding to library. Please upgrade your package'),
      };
    case 'play':
    default:
      return {
        notLoggedIn: message('To play music, you need to register for a free account'),
        noPermission: message('Your current plan does not allow music playback. Please upgrade your package'),
      };
  }
}

function getRequiredPermission(actionType: ActionType): string {
  switch (actionType) {
    case 'like':
      return 'tracks.like';
    case 'follow':
      return 'artists.follow';
    case 'add-to-library':
      return 'tracks.like';
    case 'play':
    default:
      return 'music.play';
  }
}

function getRestrictionInfo(actionType: ActionType) {
  const user = getBootstrapData().user;
  const guestRole = getBootstrapData().guest_role;
  const isLoggedIn = !!user;
  const permissions = isLoggedIn
    ? user?.permissions
    : actionType === 'play'
      ? guestRole?.permissions
      : null;
  const requiredPermission = getRequiredPermission(actionType);
  const hasPermission =
    permissions?.find(
      p => p.name === requiredPermission || p.name === 'admin',
    ) != null;
  const hasSubscription = !!user?.subscriptions?.find(sub => sub.valid);

  return {
    isLoggedIn,
    hasSubscription,
    hasPermission,
  };
}

export function useAuthClickCapture(actionType: ActionType = 'play') {
  const dialogContext = useDialogContext();

  return useCallback(
    (e: MouseEvent) => {
      const restrictionInfo = getRestrictionInfo(actionType);
      const messages = getActionMessage(actionType);

      if (!restrictionInfo.hasPermission) {
        e.preventDefault();
        e.stopPropagation();

        if (dialogContext) {
          dialogContext.close();
        }

        if (restrictionInfo.isLoggedIn) {
          toast.danger(messages.noPermission, {
            action: {
              label: message('Upgrade'),
              link: '/pricing',
            },
          });
        } else {
          toast.danger(messages.notLoggedIn, {
            action: {
              label: message('Register'),
              link: '/register',
            },
          });
        }
      }
    },
    [dialogContext, actionType],
  );
}
