import { apiClient } from '@common/http/query-client';
import { getBootstrapData } from '@ui/bootstrap-data/bootstrap-data-store';
import { IconButton } from '@ui/buttons/icon-button';
import { AttachFileIcon } from '@ui/icons/material/AttachFile';
import { SendIcon } from '@ui/icons/material/Send';
import { useSettings } from '@ui/settings/use-settings';
import { toast } from '@ui/toast/toast';
import { KeyboardEvent, useCallback, useMemo, useRef, useState } from 'react';
import { FileEntry } from './chat-types';
import { useSendMessage } from './requests/use-send-message';

function getAttachmentUrl(url: string, baseUrl: string): string {
  if (!url) return url;
  if (url.startsWith('http://') || url.startsWith('https://') || url.startsWith('//')) {
    return url;
  }
  const currentOrigin =
    typeof window !== 'undefined' ? window.location.origin : baseUrl;
  if (!currentOrigin) return `/${url.replace(/^\/+/, '')}`;
  return `${currentOrigin.replace(/\/+$/, '')}/${url.replace(/^\/+/, '')}`;
}

interface MessageComposerProps {
  conversationId: number;
  onMessageSent?: () => void;
}

export function MessageComposer({conversationId, onMessageSent}: MessageComposerProps) {
  const [message, setMessage] = useState('');
  const [attachments, setAttachments] = useState<FileEntry[]>([]);
  const [uploadingFiles, setUploadingFiles] = useState<Set<string>>(new Set());
  const {mutate: sendMessage, isPending} = useSendMessage(conversationId);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const {base_url} = useSettings();

  const maxFileSize = useMemo(() => {
    const bootstrapData = getBootstrapData();
    const uploadType = bootstrapData.uploading_types?.chatAttachment;
    const configuredMax = uploadType?.max_file_size
      ? parseInt(`${uploadType.max_file_size}`)
      : 5 * 1024 * 1024; // Fallback to 5MB

    // Use the minimum of PHP's limit and configured limit
    const phpMaxBytes = bootstrapData.php_max_upload_size?.bytes;
    if (phpMaxBytes) {
      return Math.min(configuredMax, phpMaxBytes);
    }

    return configuredMax;
  }, []);

  const handleSend = () => {
    if ((!message.trim() && attachments.length === 0) || isPending) return;

    onMessageSent?.();

    sendMessage(
      {
        body: message.trim() || undefined,
        attachments: attachments.length > 0 ? attachments.map(a => a.id) : undefined,
      },
      {
        onSuccess: () => {
          setMessage('');
          setAttachments([]);
        },
      },
    );
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleAttachClick = useCallback(() => {
    fileInputRef.current?.click();
  }, []);

  const handleFileChange = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (!files || files.length === 0) return;

      const fileArray = Array.from(files);
      const maxFiles = 5;

      if (attachments.length + fileArray.length > maxFiles) {
        toast.danger(`Maximum ${maxFiles} attachments allowed`);
        if (fileInputRef.current) {
          fileInputRef.current.value = '';
        }
        return;
      }

      // Validate file sizes before upload using configured max_file_size
      const oversizedFiles = fileArray.filter(file => file.size > maxFileSize);
      if (oversizedFiles.length > 0) {
        const maxSizeMB = (maxFileSize / (1024 * 1024)).toFixed(1);
        toast.danger(
          `File${oversizedFiles.length > 1 ? 's' : ''} too large. Maximum size is ${maxSizeMB}MB.`,
        );
        if (fileInputRef.current) {
          fileInputRef.current.value = '';
        }
        return;
      }

      for (const file of fileArray) {
        const fileId = `${file.name}-${Date.now()}`;
        setUploadingFiles(prev => new Set(prev).add(fileId));

        try {
          const formData = new FormData();
          formData.set('file', file);
          formData.set('clientMime', file.type);
          formData.set('clientExtension', file.name.split('.').pop() || '');
          formData.set('uploadType', 'chatAttachment');

          const response = await apiClient.post<{fileEntry: FileEntry}>(
            'file-entries',
            formData,
          );

          if (response.data.fileEntry) {
            setAttachments(prev => [...prev, response.data.fileEntry]);
          }
        } catch (error: any) {
          const errorMessage =
            error?.response?.data?.message ||
            error?.response?.data?.errors?.file?.[0] ||
            error?.message ||
            'Failed to upload file';
          console.error('File upload error:', error);
          toast.danger(errorMessage);
        } finally {
          setUploadingFiles(prev => {
            const next = new Set(prev);
            next.delete(fileId);
            return next;
          });
        }
      }

      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    },
    [attachments.length, maxFileSize],
  );

  const removeAttachment = useCallback((id: number) => {
    setAttachments(prev => prev.filter(a => a.id !== id));
  }, []);

  const isImageFile = useCallback((attachment: FileEntry) => {
    return (
      attachment.mime?.startsWith('image/') ||
      /\.(jpg|jpeg|png|gif|webp|svg)$/i.test(attachment.name || '')
    );
  }, []);

  return (
    <div>
      {/* Attachment preview strip above composer */}
      {attachments.length > 0 && (
        <div className="px-5 pt-4 pb-2 border-b border-divider/30">
          <div className="flex gap-3 overflow-x-auto pb-1">
            {attachments.map(attachment => {
              const isImage = isImageFile(attachment);
              return (
                <div
                  key={attachment.id}
                  className="relative flex-shrink-0"
                >
                  {isImage ? (
                    <div className="relative">
                      <img
                        src={getAttachmentUrl(attachment.url, base_url)}
                        alt={attachment.name || 'Preview'}
                        className="h-48 max-w-[280px] object-cover rounded-lg border border-divider shadow-sm"
                      />
                      <button
                        onClick={() => removeAttachment(attachment.id)}
                        className="absolute -top-2 -right-2 w-6 h-6 bg-danger text-white rounded-full flex items-center justify-center text-xs hover:bg-danger/90 transition-all shadow-md hover:scale-110"
                        type="button"
                        aria-label="Remove image"
                      >
                        ×
                      </button>
                      <div className="absolute bottom-0 left-0 right-0 bg-black/50 text-white text-xs px-2 py-1 rounded-b-lg truncate">
                        {attachment.name}
                      </div>
                    </div>
                  ) : (
                    <div className="relative flex items-center gap-2 bg-elevated px-4 py-3 rounded-lg text-sm border border-divider/30 shadow-sm h-32 min-w-[140px]">
                      <span className="truncate max-w-[120px]">{attachment.name}</span>
                      <button
                        onClick={() => removeAttachment(attachment.id)}
                        className="absolute -top-2 -right-2 w-6 h-6 bg-danger text-white rounded-full flex items-center justify-center text-xs hover:bg-danger/90 transition-all shadow-md hover:scale-110"
                        type="button"
                        aria-label="Remove file"
                      >
                        ×
                      </button>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
      {/* Input row */}
      <div className="p-5 flex items-end gap-3">
        <input
          ref={fileInputRef}
          type="file"
          multiple
          className="hidden"
          onChange={handleFileChange}
          accept="image/*,.pdf,.doc,.docx"
        />
        <textarea
          value={message}
          onChange={e => setMessage(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Type a message..."
          className="flex-1 resize-none bg-elevated border border-divider/50 rounded-2xl px-5 py-4 focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all min-h-[56px] max-h-[120px] text-sm placeholder:text-muted"
          style={{fontFamily: 'var(--be-font-family, inherit)'}}
          rows={1}
          disabled={isPending}
        />
        <IconButton
          onClick={handleAttachClick}
          disabled={isPending || uploadingFiles.size > 0}
          size="md"
          variant="flat"
          className="flex-shrink-0"
        >
          <AttachFileIcon />
        </IconButton>
        <IconButton
          onClick={handleSend}
          disabled={(!message.trim() && attachments.length === 0) || isPending}
          color="primary"
          variant="flat"
          radius="rounded-full"
          size="md"
          className="flex-shrink-0 shadow-md hover:shadow-lg transition-shadow"
        >
          <SendIcon />
        </IconButton>
      </div>
    </div>
  );
}
