import { setEchoSocketId } from '@common/http/get-echo-socket-id';
import { getBootstrapData } from '@ui/bootstrap-data/bootstrap-data-store';
import Echo from 'laravel-echo';
import Pusher from 'pusher-js';

interface EchoMeta {
  userId: number | null;
  csrfToken: string | null;
  driver: string;
  baseUrl: string;
  key?: string | null;
  host?: string | null;
  port?: number | string | null;
  cluster?: string | null;
}

declare global {
  interface Window {
    Pusher: typeof Pusher;
    __chatEchoMeta?: EchoMeta;
    __chatEchoVisibilityHandler?: () => void;
  }
}

function disconnectEcho() {
  try {
    if (typeof document !== 'undefined' && window.__chatEchoVisibilityHandler) {
      document.removeEventListener(
        'visibilitychange',
        window.__chatEchoVisibilityHandler,
      );
    }
  } catch (e) {
  } finally {
    window.__chatEchoVisibilityHandler = undefined;
  }

  const echo = window.Echo as any;
  if (echo) {
    try {
      echo.disconnect?.();
    } catch (e) {
    }
    try {
      echo.connector?.pusher?.disconnect?.();
    } catch (e) {
    }
  }

  setEchoSocketId(null);
  window.Echo = undefined;
  window.__chatEchoMeta = undefined;
}

export function initEcho() {
  const bootstrapData = getBootstrapData();
  const broadcasting = bootstrapData.settings?.broadcasting;
  const baseUrl = bootstrapData.settings?.base_url || window.location.origin;

  if (!broadcasting || !broadcasting.driver || broadcasting.driver === 'null') {
    if (window.Echo) {
      disconnectEcho();
    }
    return null;
  }

  const nextMeta: EchoMeta = {
    userId: bootstrapData.user?.id ?? null,
    csrfToken: bootstrapData.csrf_token ?? null,
    driver: broadcasting.driver,
    baseUrl,
    key: broadcasting.key ?? null,
    host: broadcasting.host ?? null,
    port: broadcasting.port ?? null,
    cluster: broadcasting.cluster ?? null,
  };

  if (window.Echo && window.__chatEchoMeta) {
    const previousMeta = window.__chatEchoMeta;
    const sameContext =
      previousMeta.userId === nextMeta.userId &&
      previousMeta.csrfToken === nextMeta.csrfToken &&
      previousMeta.driver === nextMeta.driver &&
      previousMeta.baseUrl === nextMeta.baseUrl &&
      previousMeta.key === nextMeta.key &&
      previousMeta.host === nextMeta.host &&
      previousMeta.port === nextMeta.port &&
      previousMeta.cluster === nextMeta.cluster;

    if (sameContext) {
      return window.Echo;
    }

    disconnectEcho();
  } else if (window.Echo) {
    // Safety fallback for legacy sessions where metadata was not set.
    disconnectEcho();
  }

  window.Pusher = Pusher;

  let config: any = {
    enabledTransports: ['ws', 'wss'],
    authEndpoint: `${baseUrl}/broadcasting/auth`,
    auth: {
      headers: {
        'X-CSRF-TOKEN': bootstrapData.csrf_token,
      },
    },
  };

  if (broadcasting.driver === 'reverb') {
    config.broadcaster = 'reverb';
    config.key = broadcasting.key || 'app-key';
    config.wsHost = broadcasting.host || window.location.hostname;
    config.wsPort = broadcasting.port || 8080;
    config.wssPort = broadcasting.port || 8080;
    const useTls = (broadcasting.scheme || 'https') === 'https';
    config.forceTLS = useTls;
    config.enabledTransports = useTls ? ['wss'] : ['ws'];
  } else if (broadcasting.driver === 'pusher') {
    config.broadcaster = 'pusher';
    config.key = broadcasting.key;
    config.cluster = broadcasting.cluster || 'mt1';
    config.forceTLS = true;
  } else {
    return null;
  }

  try {
    window.Echo = new Echo(config);
    window.__chatEchoMeta = nextMeta;

    const pusher = (window.Echo as any).connector?.pusher;
    if (pusher) {
      pusher.connection.bind('connected', () => {
        setEchoSocketId(pusher.connection.socket_id);
      });

      pusher.connection.bind('disconnected', () => {
        setEchoSocketId(null);
      });

      pusher.connection.bind('unavailable', () => {
        setEchoSocketId(null);
      });

      pusher.connection.bind('failed', () => {
        setEchoSocketId(null);
      });

      if (typeof document !== 'undefined') {
        const visibilityHandler = () => {
          if (!document.hidden && pusher.connection.state !== 'connected') {
            if (pusher.connection.state === 'disconnected' || pusher.connection.state === 'unavailable') {
              pusher.connect();
            }
          }
        };
        window.__chatEchoVisibilityHandler = visibilityHandler;
        document.addEventListener('visibilitychange', visibilityHandler);
      }
    }

    return window.Echo;
  } catch (error) {
    return null;
  }
}
