import { apiClient } from '@common/http/query-client';
import { useQuery } from '@tanstack/react-query';
import { Avatar } from '@ui/avatar/avatar';
import { TextField } from '@ui/forms/input-field/text-field/text-field';
import { SearchIcon } from '@ui/icons/material/Search';
import { Skeleton } from '@ui/skeleton/skeleton';
import { useState } from 'react';
import { useCreateConversation } from './requests/use-create-conversation';

interface User {
  id: number;
  name: string;
  image?: string;
  artist_id?: number;
}

interface UserSearchResponse {
  results: User[];
}

interface UserSearchProps {
  onConversationCreated: (conversationId: number) => void;
}

export function UserSearch({onConversationCreated}: UserSearchProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const createConversation = useCreateConversation();

  const {data, isLoading, error} = useQuery({
    queryKey: ['user-search', searchQuery],
    queryFn: async () => {
      const response = await apiClient.get<{pagination: {data: User[]}}>('conversations/search-users', {
        params: {
          query: searchQuery,
          perPage: 10,
        },
      });
      const results = response.data.pagination?.data || [];
      return {results};
    },
    enabled: searchQuery.length >= 2,
  });

  const handleSelectUser = async (userId: number) => {
    try {
      const conversation = await createConversation.mutateAsync({
        recipient_id: userId,
      });
      onConversationCreated(conversation.id);
      setSearchQuery('');
    } catch (error) {
    }
  };

  return (
    <div className="flex flex-col h-full">
      {/* Search input */}
      <div className="p-4 border-b">
        <TextField
          placeholder="Search users or artists..."
          value={searchQuery}
          onChange={e => setSearchQuery(e.target.value)}
          startAdornment={<SearchIcon />}
          autoFocus
        />
      </div>

      {/* Results */}
      <div className="flex-1 overflow-y-auto">
        {searchQuery.length < 2 ? (
          <div className="flex items-center justify-center h-full p-8 text-center">
            <div className="text-muted text-sm">
              Type at least 2 characters to search
            </div>
          </div>
        ) : isLoading ? (
          <div className="p-4 space-y-2">
            {[...Array(5)].map((_, i) => (
              <div key={i} className="flex items-center gap-3 p-3">
                <Skeleton
                  variant="rect"
                  size="w-12 h-12"
                  radius="rounded-full"
                />
                <div className="flex-1">
                  <Skeleton className="h-4 w-32 mb-2" />
                  <Skeleton className="h-3 w-24" />
                </div>
              </div>
            ))}
          </div>
        ) : data?.results && data.results.length > 0 ? (
          <div>
            {data.results.map(user => (
              <button
                key={user.id}
                onClick={() => handleSelectUser(user.id)}
                className="w-full flex items-center gap-3 p-3 hover:bg-hover transition-colors border-b border-divider"
              >
                <Avatar src={user.image} label={user.name} size="md" circle />
                <div className="flex-1 text-left min-w-0">
                  <div className="text-sm font-medium truncate">
                    {user.name}
                  </div>
                  {user.artist_id && (
                    <div className="text-xs text-muted">Artist</div>
                  )}
                </div>
              </button>
            ))}
          </div>
        ) : (
          <div className="flex items-center justify-center h-full p-8 text-center">
            <div className="text-muted text-sm">No users found</div>
          </div>
        )}
      </div>
    </div>
  );
}
