import {useQuery} from '@tanstack/react-query';
import {apiClient} from '@common/http/query-client';
import {ChatConversation, ChatMessage} from '../chat-types';

interface FetchConversationResponse {
  conversation: ChatConversation;
  messages: {
    data: ChatMessage[];
  };
}

export function useFetchConversation(conversationId: number | null) {
  return useQuery({
    queryKey: ['chat', 'conversation', conversationId],
    queryFn: () =>
      apiClient
        .get<FetchConversationResponse>(`conversations/${conversationId}`)
        .then(response => response.data),
    enabled: !!conversationId,
    // Optimize refetch behavior to reduce unnecessary requests
    staleTime: 1000, // Consider data fresh for 1 second
    refetchOnWindowFocus: false, // Don't refetch on window focus (WebSocket handles updates)
    refetchOnMount: false, // Don't refetch on mount if data exists (WebSocket handles updates)
  });
}
