import {useMutation, useQueryClient} from '@tanstack/react-query';
import {apiClient} from '@common/http/query-client';
import {ChatConversation, CreateConversationPayload} from '../chat-types';
import {toast} from '@ui/toast/toast';

interface CreateConversationResponse {
  conversation: ChatConversation;
}

export function useCreateConversation() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (payload: CreateConversationPayload) =>
      apiClient
        .post<CreateConversationResponse>('conversations', payload)
        .then(response => response.data.conversation),

    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: ['chat', 'conversations'],
      });
    },

    onError: () => {
      toast.danger('Failed to create conversation');
    },
  });
}
