import { useMarkNotificationsAsRead } from '@common/notifications/requests/use-mark-notifications-as-read';
import { useQueryClient } from '@tanstack/react-query';
import { IconButton } from '@ui/buttons/icon-button';
import { AddIcon } from '@ui/icons/material/Add';
import { ArrowBackIcon } from '@ui/icons/material/ArrowBack';
import { ChatIcon } from '@ui/icons/material/Chat';
import { MinimizeIcon } from '@ui/icons/material/Minimize';
