interface ChatWidgetContextValue {
  setIsOpen: (open: boolean) => void;
  unreadCount: number;
}

const ChatWidgetContext = createContext<ChatWidgetContextValue | null>(null);

export function useChatWidget() {
  return useContext(ChatWidgetContext);
}

// Tracks whether a conversation is actively being viewed (mutes notification sound)
let isChatConversationActive = false;

export function ChatWidgetProvider({children}: {children: React.ReactNode}) {
  const {user} = useAuth();
  const {data: conversations} = useFetchConversations();
  const queryClient = useQueryClient();

  const unreadCount =
    conversations?.reduce((sum, conv) => {
      return sum + (conv.unread_count || 0);
    }, 0) || 0;

  const prevUnreadRef = useRef<number | null>(null);
  useEffect(() => {
    if (conversations === undefined) return;
    if (prevUnreadRef.current === null) {
      prevUnreadRef.current = unreadCount;
      return;
    }
    const shouldPlay = unreadCount > prevUnreadRef.current && !isChatConversationActive;
    if (shouldPlay) {
      playNotificationSound();
    }
    prevUnreadRef.current = unreadCount;
  }, [unreadCount, conversations]);

  const setIsOpenWrapper = useCallback((open: boolean) => {
    const event = new CustomEvent('chat-widget-toggle', {detail: {open}});
    window.dispatchEvent(event);
  }, []);

  useEffect(() => {
    if (!user?.id) return;
    initEcho();
  }, [user?.id]);

  useEffect(() => {
    if (!user?.id) return;
    const echo = initEcho();
    if (!echo) return;
    const channelName = `App.User.${user.id}`;
    const channel = (echo as any).private(channelName);
    channel.listen('.ChatListNeedsRefresh', () => {
      queryClient.refetchQueries({queryKey: ['chat', 'conversations']});
    });
    return () => {
      if (typeof (channel as any).stopListening === 'function') {
        (channel as any).stopListening('.ChatListNeedsRefresh');
      }
      if (typeof (channel as any).unsubscribe === 'function') {
        (channel as any).unsubscribe();
      }
    };
  }, [user?.id, queryClient]);

  useEffect(() => {
    if (!user?.id) return;
    const POLL_MS = 25000;
    const interval = setInterval(() => {
      if (document.visibilityState === 'visible') {
        queryClient.refetchQueries({queryKey: ['chat', 'conversations']});
      }
    }, POLL_MS);
    return () => clearInterval(interval);
  }, [user?.id, queryClient]);

  const contextValue: ChatWidgetContextValue = {
    setIsOpen: setIsOpenWrapper,
    unreadCount
  };

  return (
    <ChatWidgetContext.Provider value={contextValue}>
      {children}
    </ChatWidgetContext.Provider>
  );
}

export function ChatWidget() {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedConversation, setSelectedConversation] = useState<
    number | null
  >(null);
  const [isSearching, setIsSearching] = useState(false);
  const {data: conversations, refetch: refetchConversations} = useFetchConversations();
  const queryClient = useQueryClient();
  const invalidateTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Mute notification sound while user is viewing a conversation
  useEffect(() => {
    isChatConversationActive = isOpen && !!selectedConversation;
    return () => { isChatConversationActive = false; };
  }, [isOpen, selectedConversation]);

  const listVisible = isOpen && !selectedConversation && !isSearching;
  useEffect(() => {
    if (!listVisible) return;
    queryClient.refetchQueries({queryKey: ['chat', 'conversations']});
  }, [listVisible, queryClient]);

  useEffect(() => {
    if (!listVisible) return;
    const catchUpRefetch = setTimeout(() => {
      queryClient.refetchQueries({queryKey: ['chat', 'conversations']});
    }, 600);
    return () => clearTimeout(catchUpRefetch);
  }, [listVisible, queryClient]);

  const LIST_POLL_INTERVAL_MS = 30000;
  useEffect(() => {
    if (!listVisible) return;
    const interval = setInterval(() => {
      const echoState = (window.Echo as any)?.connector?.pusher?.connection?.state;
      const websocketConnected = echoState === 'connected';

      // Use polling only as a fallback when websocket is unavailable.
      if (!websocketConnected) {
        queryClient.refetchQueries({queryKey: ['chat', 'conversations']});
      }
    }, LIST_POLL_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [listVisible, queryClient]);

  const CONVERSATION_STALE_MS = 15000;
  useEffect(() => {
    if (!selectedConversation) return;
    const state = queryClient.getQueryState(['chat', 'conversation', selectedConversation]);
    const dataAge = state?.dataUpdatedAt ? Date.now() - state.dataUpdatedAt : Infinity;
    if (dataAge > CONVERSATION_STALE_MS) {
      queryClient.refetchQueries({queryKey: ['chat', 'conversation', selectedConversation]});
    }
  }, [selectedConversation, queryClient]);

  // Calculate total unread count
  const unreadCount =
    conversations?.reduce((sum, conv) => {
      return sum + (conv.unread_count || 0);
    }, 0) || 0;

  const handleOpenChatWidget = useCallback(() => {
    setIsOpen(true);
  }, []);

  // Create stable setIsOpen wrapper
  const setIsOpenWrapper = useCallback((open: boolean) => {
    if (open) {
      handleOpenChatWidget();
    } else {
      setIsOpen(false);
    }
  }, [handleOpenChatWidget]);

  // Listen for toggle events from provider
  useEffect(() => {
    const handleToggle = (event: CustomEvent) => {
      const {open} = event.detail;
      if (open) {
        handleOpenChatWidget();
      } else {
        setIsOpen(false);
      }
    };

    window.addEventListener('chat-widget-toggle' as any, handleToggle as EventListener);
    return () => {
      window.removeEventListener('chat-widget-toggle' as any, handleToggle as EventListener);
    };
  }, [handleOpenChatWidget]);

  // Persist open state
  useEffect(() => {
    const saved = localStorage.getItem('chat_widget_open');
    if (saved) {
      setIsOpen(JSON.parse(saved));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('chat_widget_open', JSON.stringify(isOpen));
  }, [isOpen]);

  // Listen for open chat widget events
  useEffect(() => {
    const handleOpenChatEvent = (event: CustomEvent) => {
      const {conversationId} = event.detail;
      handleOpenChatWidget();
      setIsSearching(false);
      if (conversationId) {
        setSelectedConversation(conversationId);
      }
    };

    window.addEventListener(
      'open-chat-widget' as any,
      handleOpenChatEvent as EventListener,
    );
    return () => {
      window.removeEventListener(
        'open-chat-widget' as any,
        handleOpenChatEvent as EventListener,
      );
    };
  }, [handleOpenChatWidget]);

  return (
    <>
      {/* Widget popup */}
      {isOpen && (
        <div className="fixed bottom-24 right-6 z-40 w-[400px] min-w-[400px] max-w-[90vw] h-[600px] bg rounded-lg shadow-2xl flex flex-col overflow-hidden border">
          {/* Header */}
          <div className="flex items-center justify-between px-4 py-3 bg-primary text-white">
            <div className="flex items-center gap-2 flex-1 min-w-0">
              {isSearching || selectedConversation ? (
                <IconButton
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    try {
                      setIsSearching(false);
                      setSelectedConversation(null);
                    } catch (error) {
                    }
                  }}
                  className="text-white hover:bg-primary-dark"
                  size="sm"
                  type="button"
                  title="Back"
                >
                  <ArrowBackIcon />
                </IconButton>
              ) : (
                <ChatIcon className="w-5 h-5 flex-shrink-0" />
              )}
              <h3 className="font-semibold truncate" style={{fontFamily: 'var(--be-font-family, inherit)'}}>
                {isSearching
                  ? 'New Message'
                  : selectedConversation
                    ? 'Conversation'
                    : 'Messages'}
              </h3>
            </div>
            <div className="flex items-center gap-1 flex-shrink-0">
              {!isSearching && !selectedConversation && (
                <IconButton
                  onClick={() => {
                    try {
                      setIsSearching(true);
                    } catch (error) {
                    }
                  }}
                  className="text-white hover:bg-primary-dark"
                  size="sm"
                  title="New message"
                  type="button"
                >
                  <AddIcon />
                </IconButton>
              )}
              <IconButton
                onClick={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  try {
                    setIsOpen(false);
                  } catch (error) {
                  }
                }}
                className="text-white hover:bg-primary-dark"
                size="sm"
                type="button"
                title="Minimize"
              >
                <MinimizeIcon />
              </IconButton>
            </div>
          </div>

          {/* Content */}
          <div className="flex-1 overflow-hidden">
            {isSearching ? (
              <UserSearch
                onConversationCreated={id => {
                  setIsSearching(false);
                  setSelectedConversation(id);
                }}
              />
            ) : selectedConversation ? (
              <ConversationView
                conversationId={selectedConversation}
                onBack={() => {
                  setSelectedConversation(null);
                }}
              />
            ) : (
              <ConversationList
                onSelectConversation={id => setSelectedConversation(id)}
                selectedConversationId={selectedConversation}
                onConversationArchived={id => {
                  if (selectedConversation === id) setSelectedConversation(null);
                }}
              />
            )}
          </div>
        </div>
      )}
    </>
  );
}

export function ChatNotificationItem(props: NotificationListItemProps) {
  const { notification, isLast } = props;
  const markAsRead = useMarkNotificationsAsRead();
  const { close } = useDialogContext();

  const handleClick = () => {
    if (!markAsRead.isPending && !notification.read_at) {
      markAsRead.mutate({ ids: [notification.id] });
    }
    window.dispatchEvent(new CustomEvent('chat-widget-toggle', { detail: { open: true } }));
    close();
  };

  return (
    <div
      onClick={handleClick}
      className={`relative flex items-start gap-14 bg-alt px-32 py-20 cursor-pointer ${
        !isLast ? 'border-b' : ''
      } ${!notification.read_at ? 'bg-elevated hover:bg-primary/10' : 'hover:bg-hover'}`}
    >
      {!notification.data.image && !notification.read_at && (
        <div className="absolute left-16 top-26 h-8 w-8 flex-shrink-0 rounded-full bg-primary shadow" />
      )}
      {notification.data.image && (
        <MixedImage className="h-24 w-24 flex-shrink-0 rounded object-cover" src={notification.data.image} />
      )}
      <div className="min-w-0">
        {notification.data.lines?.map((line: any, index: number) => (
          <Line notification={notification} line={line} index={index} key={index} />
        ))}
      </div>
    </div>
  );
}
