import { useAuth } from '@common/auth/use-auth';
import { useSettings } from '@ui/settings/use-settings';
import { Avatar } from '@ui/avatar/avatar';
import { FormattedDate } from '@ui/i18n/formatted-date';
import { Skeleton } from '@ui/skeleton/skeleton';
import { IconButton } from '@ui/buttons/icon-button';
import { RefreshIcon } from '@ui/icons/material/Refresh';
import { useEffect, useRef, useCallback, useMemo, memo } from 'react';
import { ChatMessage } from './chat-types';
import { useListenToMessages } from './hooks/use-listen-to-messages';
import { initEcho } from './init-echo';
import { MessageComposer } from './message-composer';
import { useFetchConversation } from './requests/use-fetch-conversation';
import { useMarkAsRead } from './requests/use-mark-as-read';
import { useSendMessage } from './requests/use-send-message';

function getAttachmentUrl(url: string, baseUrl: string): string {
  if (!url) return url;
  if (url.startsWith('http://') || url.startsWith('https://') || url.startsWith('//')) {
    return url;
  }
  const currentOrigin =
    typeof window !== 'undefined' ? window.location.origin : baseUrl;
  if (!currentOrigin) return `/${url.replace(/^\/+/, '')}`;
  return `${currentOrigin.replace(/\/+$/, '')}/${url.replace(/^\/+/, '')}`;
}

interface ConversationViewProps {
  conversationId: number;
  onBack?: () => void;
}

export function ConversationView({
  conversationId,
  onBack,
}: ConversationViewProps) {
  const {data, isLoading, error} = useFetchConversation(conversationId);
  const {mutate: markAsRead} = useMarkAsRead(conversationId);
  const {mutate: sendMessage} = useSendMessage(conversationId);
  const {user} = useAuth();
  const {base_url} = useSettings();
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const conversation = data?.conversation;
  const messages = useMemo(() => data?.messages?.data || [], [data?.messages?.data]);
  const otherUser = conversation?.other_user;
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const lastMessageIdRef = useRef<string | number | null>(null);
  useEffect(() => {
    initEcho();
  }, []);

  const scrollToBottom = useCallback(() => {
    const container = messagesContainerRef.current;
    if (container) {
      container.scrollTop = container.scrollHeight;
    }
  }, []);

  useListenToMessages(conversationId, scrollToBottom);

  // Mark as read when conversation is opened - only run once when conversation changes
  useEffect(() => {
    if (conversation && (conversation.unread_count || 0) > 0) {
      markAsRead();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [conversation?.id, conversation?.unread_count]);

  // Scroll to bottom on new messages
  // Messages are ordered desc from API, so messages[0] is the newest
  useEffect(() => {
    if (messages.length === 0) return;

    const newestMessage = messages[0];
    const newestMessageId = newestMessage.id as string | number;
    const isNewMessage = lastMessageIdRef.current !== newestMessageId;
    const isInitialLoad = lastMessageIdRef.current === null;
    const isOwnMessage = newestMessage.user_id === user?.id;
    const isTempMessage = typeof newestMessageId === 'string' && newestMessageId.startsWith('temp-');

    if (isNewMessage || isInitialLoad) {
      const shouldScroll = isInitialLoad || isOwnMessage || isTempMessage || (() => {
        const container = messagesContainerRef.current;
        if (!container) return false;
        const distanceFromBottom = container.scrollHeight - container.scrollTop - container.clientHeight;
        return distanceFromBottom < 500;
      })();

      if (shouldScroll) {
        // Scroll immediately, then again after images may have loaded
        scrollToBottom();
        setTimeout(scrollToBottom, 300);
        setTimeout(scrollToBottom, 800);
      }
      lastMessageIdRef.current = newestMessageId;
    }
  }, [messages, user?.id, scrollToBottom]);

  // Memoize the retry handler to prevent re-creating on every render
  // IMPORTANT: Must be before any conditional returns to follow Rules of Hooks
  const handleRetry = useCallback(
    (failedMessage: ChatMessage) => {
      sendMessage({
        body: failedMessage.body || undefined,
        attachments: failedMessage.attachments?.map((a: any) => a.id) || undefined,
      });
    },
    [sendMessage]
  );


  if (isLoading) {
    return (
      <div className="flex flex-col h-full">
        <div className="p-4 border-b border-divider flex items-center gap-3">
          <Skeleton variant="rect" size="w-10 h-10" radius="rounded-full" />
          <Skeleton className="h-5 w-32" />
        </div>
        <div className="flex-1 p-4 space-y-4">
          {[...Array(5)].map((_, i) => (
            <div key={i} className={i % 2 === 0 ? 'text-right' : 'text-left'}>
              <Skeleton className="inline-block h-16 w-64" />
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-full p-8">
        <div className="text-center">
          <div className="text-danger font-medium mb-2">Failed to load messages</div>
          <div className="text-muted text-xs">{(error as any)?.response?.data?.message || (error as any)?.message || 'Unknown error'}</div>
        </div>
      </div>
    );
  }

  if (!conversation) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-muted">Conversation not found</div>
      </div>
    );
  }

  const handleBack = () => {
    if (onBack) {
      try {
        onBack();
      } catch (error) {
      }
    }
  };

  return (
    <div className="flex flex-col h-full bg-bg" style={{fontFamily: 'var(--be-font-family, inherit)'}}>
      {/* Header */}
      <div className="px-5 py-4 border-b border-divider/50 flex items-center gap-3 bg-elevated/80 backdrop-blur-sm">
        <Avatar
          src={otherUser?.image || undefined}
          label={otherUser?.name || otherUser?.username || `User ${conversation?.user_one_id === user?.id ? conversation?.user_two_id : conversation?.user_one_id}` || 'User'}
          size="md"
          circle
          fallback="initials"
        />
        <div className="font-semibold text-base text-main" style={{fontFamily: 'var(--be-font-family, inherit)'}}>
          {otherUser?.name || otherUser?.username || `User ${conversation?.user_one_id === user?.id ? conversation?.user_two_id : conversation?.user_one_id}` || 'User'}
        </div>
      </div>

      {/* Messages */}
      <div ref={messagesContainerRef} className="flex-1 overflow-y-auto px-5 py-8 bg-gradient-to-b from-bg to-bg/95">
        {messages.length === 0 ? (
          <div className="flex items-center justify-center h-full text-muted text-sm" style={{fontFamily: 'var(--be-font-family, inherit)'}}>
            No messages yet. Start the conversation!
          </div>
        ) : (
          <MessageList
            messages={messages}
            userId={user?.id}
            otherUserName={otherUser?.name}
            onRetry={handleRetry}
            baseUrl={base_url}
          />
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Composer */}
      <div className="border-t border-divider/50 bg-elevated/50 backdrop-blur-sm">
        <MessageComposer conversationId={conversationId} onMessageSent={scrollToBottom} />
      </div>
    </div>
  );
}

interface MessageListProps {
  messages: ChatMessage[];
  userId?: number;
  otherUserName?: string;
  onRetry: (message: ChatMessage) => void;
  baseUrl: string;
}

const MessageList = memo(function MessageList({ messages, userId, otherUserName, onRetry, baseUrl }: MessageListProps) {
  const reversedMessages = useMemo(() => messages.slice().reverse(), [messages]);

  return (
    <div className="flex flex-col">
      {reversedMessages.map((message, index) => {
        const prevMessage = index > 0 ? reversedMessages[index - 1] : null;
        const isSameSender = prevMessage ? prevMessage.user_id === message.user_id : false;
        const isOwn = message.user_id === userId;
        return (
          <MessageBubble
            key={message.id}
            message={message}
            isOwn={isOwn}
            isSameSender={isSameSender}
            otherUserName={otherUserName}
            onRetry={onRetry}
            baseUrl={baseUrl}
          />
        );
      })}
    </div>
  );
});

interface MessageBubbleProps {
  message: ChatMessage;
  isOwn: boolean;
  isSameSender?: boolean;
  otherUserName?: string;
  onRetry?: (message: ChatMessage) => void;
  baseUrl: string;
}

const MessageBubble = memo(function MessageBubble({message, isOwn, isSameSender = false, otherUserName, onRetry, baseUrl}: MessageBubbleProps) {
  const displayName = isOwn
    ? (message.user?.name || 'You')
    : (message.user?.name || otherUserName || `User ${message.user_id}` || 'Unknown User');
  
  const messageId = message.id as string | number;
  const isTempMessage = typeof messageId === 'string' && (messageId as string).startsWith('temp-');
  const isFailed = (message as any).failed === true;
  const isSending = (message as any).sending === true;

  return (
    <div className={`w-full flex ${isOwn ? 'justify-end' : 'justify-start'} items-end gap-2 ${isSameSender ? 'mb-1 mt-0.5' : 'mb-4'}`}>
      {!isOwn && !isSameSender && (
        <Avatar
          src={message.user?.image || undefined}
          label={displayName}
          size="sm"
          circle
          fallback="initials"
          className="flex-shrink-0"
        />
      )}
      {!isOwn && isSameSender && <div className="w-8 flex-shrink-0" />}
      <div className={`max-w-[75%] ${isOwn ? 'items-end' : 'items-start'} flex flex-col gap-1.5`}>
        {!isOwn && !isSameSender && (
          <span className="text-xs font-medium text-muted px-1" style={{fontFamily: 'var(--be-font-family, inherit)'}}>
            {displayName}
          </span>
        )}
        <div
          className={`
            px-6 py-4 break-words shadow-sm
            transition-all duration-200
            ${
              isOwn
                ? isFailed
                  ? 'bg-danger/20 text-danger border-2 border-danger/50 rounded-2xl rounded-br-md'
                  : 'bg-primary text-white rounded-2xl rounded-br-md'
                : 'bg-elevated text-main rounded-2xl rounded-bl-md border border-divider/30'
            }
            ${isTempMessage && isSending ? 'opacity-70' : ''}
          `}
          style={{fontFamily: 'var(--be-font-family, inherit)'}}
        >
          {message.body && (
            <div className="whitespace-pre-wrap leading-relaxed text-sm" style={{fontFamily: 'var(--be-font-family, inherit)'}}>{message.body}</div>
          )}
          {message.attachments && message.attachments.length > 0 && (
            <div className={`mt-2 space-y-2 ${message.body ? '' : ''}`}>
              {message.attachments.map(attachment => {
                const isImage = attachment.mime?.startsWith('image/') ||
                  /\.(jpg|jpeg|png|gif|webp|svg)$/i.test(attachment.name || '');
                const attachmentUrl = getAttachmentUrl(attachment.url, baseUrl);
                const downloadUrl = attachment.hash
                  ? `/file-entries/download/${attachment.hash}`
                  : attachmentUrl;

                if (isImage) {
                  return (
                    <div key={attachment.id} className="rounded-xl overflow-hidden max-w-full shadow-md">
                      <img
                        src={attachmentUrl}
                        alt={attachment.name || 'Image attachment'}
                        className="max-w-full h-auto cursor-pointer hover:opacity-90 transition-opacity"
                        onClick={() => window.open(attachmentUrl, '_blank')}
                        loading="lazy"
                      />
                    </div>
                  );
                }

                return (
                  <a
                    key={attachment.id}
                    href={downloadUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className={`flex items-center gap-2 text-sm ${
                      isOwn ? 'text-white/90 hover:text-white' : 'text-primary hover:underline'
                    } transition-colors`}
                  >
                    📎 {attachment.name}
                  </a>
                );
              })}
            </div>
          )}
        </div>
        <div className={`text-xs text-muted mt-0.5 px-1 flex items-center gap-1 ${isOwn ? 'justify-end' : 'justify-start'}`} style={{fontFamily: 'var(--be-font-family, inherit)'}}>
          {isTempMessage && isSending && (
            <span className="opacity-70">Sending...</span>
          )}
          {isTempMessage && isFailed && (
            <div className="flex items-center gap-2">
              <span className="text-danger">Failed to send</span>
              {onRetry && (
                <IconButton
                  size="xs"
                  variant="flat"
                  color="danger"
                  onClick={() => onRetry(message)}
                  className="!h-5 !w-5"
                >
                  <RefreshIcon />
                </IconButton>
              )}
            </div>
          )}
          {!isTempMessage && (
            <>
              <FormattedDate date={message.created_at} preset="time" />
              {message.edited_at && <span className="ml-1 opacity-70">(edited)</span>}
            </>
          )}
        </div>
      </div>
      {isOwn && !isSameSender && (
        <Avatar
          src={message.user?.image || undefined}
          label={displayName}
          size="sm"
          circle
          fallback="initials"
          className="flex-shrink-0"
        />
      )}
      {isOwn && isSameSender && <div className="w-8 flex-shrink-0" />}
    </div>
  );
});
