let audioContext: AudioContext | null = null;
let audioBuffer: AudioBuffer | null = null;
let unlocked = false;
let loadPromise: Promise<boolean> | null = null;

function getAudioContext(): AudioContext | null {
  if (typeof window === 'undefined') return null;
  if (audioContext && audioContext.state !== 'closed') {
    return audioContext;
  }
  try {
    audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    return audioContext;
  } catch (e) {
    return null;
  }
}

async function loadBuffer(ctx: AudioContext): Promise<boolean> {
  if (audioBuffer) return true;
  if (!loadPromise) {
    loadPromise = (async () => {
      try {
        const response = await fetch('/notification.mp3', {cache: 'no-cache'});
        if (!response.ok) return false;
        const arrayBuffer = await response.arrayBuffer();
        audioBuffer = await ctx.decodeAudioData(arrayBuffer);
        return !!audioBuffer;
      } catch (e) {
        return false;
      } finally {
        loadPromise = null;
      }
    })();
  }
  return loadPromise;
}

const unlock = () => {
  if (unlocked) return;
  const ctx = getAudioContext();
  if (!ctx) return;
  unlocked = true;
  if (ctx.state === 'suspended') {
    void ctx.resume().catch(() => {});
  }
  void loadBuffer(ctx);
  document.removeEventListener('click', unlock);
  document.removeEventListener('touchstart', unlock);
  document.removeEventListener('keydown', unlock);
};

export function ensureUnlock() {
  unlock();
}

if (typeof window !== 'undefined') {
  document.addEventListener('click', unlock);
  document.addEventListener('touchstart', unlock);
  document.addEventListener('keydown', unlock);
}

export async function playNotificationSound() {
  const ctx = getAudioContext();
  if (!ctx || ctx.state === 'closed') {
    return;
  }
  if (ctx.state === 'suspended') {
    try {
      await ctx.resume();
    } catch (e) {
      return;
    }
  }
  if (!audioBuffer) {
    const loaded = await loadBuffer(ctx);
    if (!loaded || !audioBuffer) {
      return;
    }
  }
  const source = ctx.createBufferSource();
  const gainNode = ctx.createGain();
  gainNode.gain.value = 0.5;
  source.buffer = audioBuffer;
  source.connect(gainNode).connect(ctx.destination);
  source.start(0);
}
