import { useQueryClient } from '@tanstack/react-query';
import { useCallback, useEffect, useRef } from 'react';

declare global {
  interface Window {
    Echo?: {
      private: (channel: string) => {
        listen: (event: string, callback: (data: any) => void) => {
          listen: (event: string, callback: (data: any) => void) => any;
          stopListening: () => void;
        };
        stopListening: () => void;
      };
    };
  }
}

export function useListenToMessages(
  conversationId: number,
  onNewMessage?: () => void,
) {
  const queryClient = useQueryClient();
  const invalidateTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const pendingInvalidationRef = useRef(false);

  // Stabilize the onNewMessage callback reference using useRef
  const onNewMessageRef = useRef(onNewMessage);
  useEffect(() => {
    onNewMessageRef.current = onNewMessage;
  }, [onNewMessage]);

  // Create a debounced invalidate callback to batch rapid events
  const invalidate = useCallback(() => {
    // If there's already a pending invalidation, skip
    if (pendingInvalidationRef.current) {
      return;
    }

    pendingInvalidationRef.current = true;

    // Clear any existing timeout
    if (invalidateTimeoutRef.current) {
      clearTimeout(invalidateTimeoutRef.current);
    }

    // Batch invalidations with a small delay to avoid multiple rapid re-renders
    invalidateTimeoutRef.current = setTimeout(() => {
      // Refresh active conversation data; conversation list is updated via
      // ChatListNeedsRefresh events on App.User.{id} channel.
      queryClient.invalidateQueries({
        queryKey: ['chat', 'conversation', conversationId],
      });

      onNewMessageRef.current?.();
      pendingInvalidationRef.current = false;
    }, 50); // 50ms debounce - enough to batch rapid events but fast enough to feel instant
  }, [conversationId, queryClient]);

  useEffect(() => {
    if (!window.Echo || !conversationId) {
      return;
    }

    const channelName = `App.Conversation.${conversationId}`;
    let channel: any;

    try {
      channel = window.Echo.private(channelName);
    } catch (error) {
      return;
    }

    if (!channel) {
      return;
    }

    const handleMessageCreated = (data: any) => {
      // Force immediate invalidation without debounce to ensure all messages are processed
      invalidate();
    };

    const handleMessageUpdated = (data: any) => {
      // Force immediate invalidation
      invalidate();
    };

    const handleMessageDeleted = (data: any) => {
      // Force immediate invalidation
      invalidate();
    };

    const echoChannel = channel as any;

    if (echoChannel.subscribed) {
      echoChannel.subscribed(() => {});
    }

    if (echoChannel.error) {
      echoChannel.error(() => {});
    }

    try {
      channel.listen('.ChatMessageCreated', handleMessageCreated);
      channel.listen('.ChatMessageUpdated', handleMessageUpdated);
      channel.listen('.ChatMessageDeleted', handleMessageDeleted);
    } catch (error) {
    }

    return () => {
      if (invalidateTimeoutRef.current) {
        clearTimeout(invalidateTimeoutRef.current);
      }
      try {
        if (channel) {
          if (typeof channel.stopListening === 'function') {
            channel.stopListening('.ChatMessageCreated');
            channel.stopListening('.ChatMessageUpdated');
            channel.stopListening('.ChatMessageDeleted');
          }
          if (typeof (channel as any).unsubscribe === 'function') {
            (channel as any).unsubscribe();
          }
        }
      } catch (error) {
      }
    };
  }, [conversationId, invalidate]);
}
