import {useFetchConversations} from './requests/use-fetch-conversations';
import {useArchiveConversation} from './requests/use-archive-conversation';
import {ChatConversation} from './chat-types';
import {ContextMenuButton} from '@app/web-player/context-dialog/context-dialog-layout';
import {Avatar} from '@ui/avatar/avatar';
import {IconButton} from '@ui/buttons/icon-button';
import {FormattedRelativeTime} from '@ui/i18n/formatted-relative-time';
import {Trans} from '@ui/i18n/trans';
import {MoreVertIcon} from '@ui/icons/material/MoreVert';
import {ConfirmationDialog} from '@ui/overlays/dialog/confirmation-dialog';
import {Dialog} from '@ui/overlays/dialog/dialog';
import {DialogBody} from '@ui/overlays/dialog/dialog-body';
import {useDialogContext} from '@ui/overlays/dialog/dialog-context';
import {DialogTrigger} from '@ui/overlays/dialog/dialog-trigger';
import {closeDialog, openDialog} from '@ui/overlays/store/dialog-store';
import {Skeleton} from '@ui/skeleton/skeleton';

interface ConversationListProps {
  onSelectConversation: (id: number) => void;
  selectedConversationId?: number | null;
  onConversationArchived?: (id: number) => void;
}

export function ConversationList({
  onSelectConversation,
  selectedConversationId,
  onConversationArchived,
}: ConversationListProps) {
  const {data: conversations, isLoading} = useFetchConversations();

  if (isLoading) {
    return (
      <div className="p-4 space-y-2">
        {[...Array(5)].map((_, i) => (
          <div key={i} className="flex items-center gap-3 p-3">
            <Skeleton variant="rect" size="w-12 h-12" radius="rounded-full" />
            <div className="flex-1">
              <Skeleton className="h-4 w-32 mb-2" />
              <Skeleton className="h-3 w-48" />
            </div>
          </div>
        ))}
      </div>
    );
  }

  if (!conversations || conversations.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-8 text-center">
        <div className="text-muted text-sm">No conversations yet</div>
        <div className="text-muted text-xs mt-2">
          Start a conversation with another user
        </div>
      </div>
    );
  }

  return (
    <div className="overflow-y-auto h-full p-2">
      {conversations.map(conversation => (
        <ConversationListItem
          key={conversation.id}
          conversation={conversation}
          isSelected={conversation.id === selectedConversationId}
          onClick={() => onSelectConversation(conversation.id)}
          onConversationArchived={onConversationArchived}
        />
      ))}
    </div>
  );
}

interface ConversationListItemProps {
  conversation: ChatConversation;
  isSelected: boolean;
  onClick: () => void;
  onConversationArchived?: (id: number) => void;
}

function ConversationListItem({
  conversation,
  isSelected,
  onClick,
  onConversationArchived,
}: ConversationListItemProps) {
  const otherUser = conversation.other_user;
  const hasUnread = (conversation.unread_count || 0) > 0;
  const archiveConversation = useArchiveConversation();

  const handleDelete = () => {
    openDialog(ConfirmationDialog, {
      isDanger: true,
      title: <Trans message="Delete chat" />,
      body: <Trans message="Remove this chat from your list? The other person will still see it." />,
      confirm: <Trans message="Delete" />,
      onConfirm: () => {
        closeDialog();
        archiveConversation.mutate(conversation.id, {
          onSuccess: () => onConversationArchived?.(conversation.id),
        });
      },
    });
  };

  const DeleteMenuItem = () => {
    const {close} = useDialogContext();
    return (
      <ContextMenuButton
        disabled={archiveConversation.isPending}
        onClick={() => {
          close();
          handleDelete();
        }}
      >
        <Trans message="Delete" />
      </ContextMenuButton>
    );
  };

  return (
    <div
      className={`
        w-full flex items-center gap-2 p-5 hover:bg-hover transition-all duration-200
        rounded-xl mb-2
        ${isSelected ? 'bg-primary/10 border border-primary/30 shadow-sm' : 'bg-elevated border border-divider/50 hover:border-divider'}
      `}
    >
      <button
        onClick={onClick}
        className="flex-1 flex items-center gap-4 min-w-0 text-left"
      >
        <Avatar
          src={otherUser?.image}
          label={otherUser?.name || otherUser?.username || `User ${conversation.user_one_id === conversation.user_two_id ? conversation.user_one_id : (conversation.user_one_id || conversation.user_two_id)}`}
          size="md"
          circle
          fallback="initials"
        />
        <div className="flex-1 min-w-0" style={{fontFamily: 'var(--be-font-family, inherit)'}}>
          <div className="flex items-center justify-between mb-2">
            <div className={`text-sm font-medium truncate ${hasUnread ? 'font-semibold' : ''}`} style={{fontFamily: 'var(--be-font-family, inherit)'}}>
              {otherUser?.name || otherUser?.username || `User ${conversation.user_one_id === conversation.user_two_id ? conversation.user_one_id : (conversation.user_one_id || conversation.user_two_id)}`}
            </div>
            {hasUnread && (
              <div className="ml-2 flex-shrink-0 flex items-center justify-center min-w-[18px] h-[18px] px-1 bg-primary text-white text-[10px] font-bold rounded-full">
                {conversation.unread_count! > 99 ? '99+' : conversation.unread_count}
              </div>
            )}
          </div>
          <div className="flex items-center justify-between">
            <div
              className={`text-xs truncate ${
                hasUnread ? 'text-main font-medium' : 'text-muted'
              }`}
            >
              {conversation.last_message_attachments_count > 0 && (
                <span className="mr-1">📎</span>
              )}
              {conversation.last_message_body || 'No messages yet'}
            </div>
            {conversation.last_message_at && !hasUnread && (
              <div className="text-xs text-muted ml-2">
                <FormattedRelativeTime date={conversation.last_message_at} />
              </div>
            )}
          </div>
        </div>
      </button>
      <DialogTrigger type="popover" mobileType="tray">
        <IconButton
          size="sm"
          className="text-muted flex-shrink-0"
          onClick={e => e.stopPropagation()}
        >
          <MoreVertIcon />
        </IconButton>
        <Dialog size="xs">
          <DialogBody padding="p-0">
            <ul className="text-base md:text-sm">
              <DeleteMenuItem />
            </ul>
          </DialogBody>
        </Dialog>
      </DialogTrigger>
    </div>
  );
}
